 return setmetatable({},{__index=function(_,k) note('get:'..label..':'..tostring(k));return t[k]end,
 __newindex=function(_,k,v)note('put:'..label..':'..tostring(k)..':'..tostring(v)); if label==FAIL then error(fault,0)end;t[k]=v end,
 __len=function()note('len:'..label);return #t end})
end
