local s=proxy({player=p,enemies=proxy({e1,e2,e3},'enemies'),hand=hand,draw={},discard=discard,exhaust={},events=events},'state')
local function gen(t,n,up)
 note('generate:'..n..':'..tostring(up))
 local one=proxy({uid=5,cardId='shiv',upgraded=false},'new1');local two=proxy({uid=6,cardId='shiv',upgraded=false},'new2')
 hand[2]=one;discard[1]=two
 events[1]={kind='silent_generate',frame={hand={proxy({uid=5},'frame1')},draw={},discard={proxy({uid=6},'frame2')},exhaust={}}};
 return {5,6}
end
-- Avoid addresses in write logs while retaining callback counts/order.
local r=table.pack(pcall(S.startTurn,s,gen));note('ok:'..tostring(r[1]));note('fault:'..tostring(r[2]==fault));note('arity:'..r.n)
return (table.concat(log,'|'):gsub('table: 0x%x+','table:<identity>'))
